                { value: "support", label: "Support assistant" },
              ]}
            />
          </ResponsiveDialog>
        ),
      }}
    />
  );
}

export function PageGutters() {
  return (
    <CollectionPage
      gutter="page"
      regions={{
        header: <PageHeader title="Conversations" />,
        collection: <p>Choose a conversation.</p>,
      }}
    />
  );
