              )}
              {regions?.inspectorActions != null && (
                <div data-rcl-collection-inspector-actions>{regions.inspectorActions}</div>
              )}
            </div>
          )}
        </div>
      </div>
      {regions?.overlays}
    </StateView>
  );
});

